// Helper to sum stock
func calculateTotalStock(stock []db.GetPartAssignmentsRow) int64 {
	var total int64 = 0
	for _, s := range stock {
		total += s.Quantity
	}
	return total
}

func barcodeText(part db.Part) string {
	if part.BarcodeData.Valid && part.BarcodeData.String != "" {
		return part.BarcodeData.String
	}
	return ""
}

